const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),os=require('node:os'),ts=require('typescript');
const source=process.env.OPENMATES_PRODUCTION_RUST_CORE_ROOT;if(!source?.startsWith('/tmp/'))throw Error('explicit_private_source_required');
const app=process.env.OPENMATES_PRODUCTION_APP_RUST_CORE_ROOT;if(!app?.startsWith('/tmp/'))throw Error('explicit_private_app_source_required');
const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'original-port-hooks-'));
