const {installBrowserCoreWorker}=require(path.join(tmp,'workerRuntime.js'));
const OWNER='11111111-1111-4111-8111-111111111111';
const held=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return{promise,resolve,reject};};const tick=()=>new Promise(r=>setImmediate(r));
class Endpoint extends EventTarget{sent=[];postMessage(v){this.sent.push(v);}receive(v){this.dispatchEvent(new MessageEvent('message',{data:v}));}}
async function fixture({enabled=true,delayed=false}={}){
 const key=await require('node:crypto').webcrypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']);
 const endpoint=new Endpoint(),finish=held(),drain=held(),calls=[];let restore=0,consumed=0,free=0,id=0;
 const status=()=>({handle:'native-original',principal:OWNER,generation:1,persisted:false,local_read_only:false,free(){}});
 const client={admitted_status:status,status,invalidate(){calls.push('invalidate')},free(){calls.push('clientfree')}};
 const port={async ready(){},revoke(){calls.push('portrevoke')},close_and_drain(){calls.push('portdrain');return drain.promise},free(){free++;calls.push('portfree')}};
 const bootstrap={free(){calls.push('bootstrapfree')},async restore_original(api,origin,session,profile){consumed++;calls.push('constructor');if(delayed)await finish.promise;
  // This fixture models an opaque already-bound Rust result, not its proof.
  return{take_port(){calls.push('takeport');return port},take_client(){calls.push('takeclient');return client},free(){calls.push('resultfree')}};}};
 const binding={PreparedBrowserProfile:{from_existing_key(){return{free(){calls.push('profilefree')}}}},BrowserCoreClient:{restore:async()=>{restore++;return client}}};
 const dispose=installBrowserCoreWorker(endpoint,binding,{apiUrl:'https://example.invalid',appOrigin:'https://example.invalid',sessionId:'fixture',admission:'existing_key',expectedPrincipal:OWNER},{request:async(_n,_o,fn)=>fn({})},enabled?bootstrap:undefined);
 function request(){const own=++id;endpoint.receive({version:1,id:own,operation:'restore_existing',key,profile:{principal:OWNER,hashedEmail:null,userEmailSalt:null},persistence:'memory_only'});return own;}
 return{endpoint,client,port,bootstrap,calls,finish,drain,dispose,request,count:()=>({restore,consumed,free})};
}
test('feature-off dispatcher uses unchanged ordinary restore and has no private native resource',async()=>{
 const f=await fixture({enabled:false});f.request();await tick();assert.equal(f.count().restore,1);assert.equal(f.count().consumed,0);assert.equal(f.endpoint.sent.at(-1).ok,true);f.dispose();assert.equal(f.calls.includes('portdrain'),false);
});
test('original opaque restore result binds before Client/status escape and port free waits actual resource drain',async()=>{
 const f=await fixture();f.request();await tick();assert.deepEqual(f.calls,['constructor','takeport','takeclient','resultfree']);assert.equal(f.count().restore,0);assert.equal(f.count().consumed,1);assert.equal(f.endpoint.sent.at(-1).status.handle,'native-original');
 f.dispose();assert.ok(f.calls.includes('portrevoke'));assert.equal(f.count().free,0);f.drain.resolve();await tick();assert.equal(f.count().free,1);
});
