 const f=await fixture({delayed:true});f.request();await tick();f.dispose();assert.equal(f.calls.includes('bootstrapfree'),false);f.finish.resolve();await tick();assert.equal(f.endpoint.sent.length,0);assert.ok(f.calls.includes('portrevoke'));assert.equal(f.count().free,0);f.drain.resolve();await tick();assert.equal(f.count().free,1);
});
