use tokio::sync::oneshot;
const MAX_PHASE_BYTES:usize=MAX_SCOPED_SAVED_SEND_QUARANTINE_BYTES;
fn bound<T:serde::Serialize+?Sized>(value:&T)->Result<()> {scoped_serialized_size(value,MAX_PHASE_BYTES).map(|_|())}
